import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static long[] pref;
    static int n;
    
    static long calc(int a, int b){
        int x = a+2*b;
        
        int y = 3*n-2*a-b;
        return 2L*pref[a]+pref[x]+3L*pref[y];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		while(t-- > 0){
		    n = sc.nextInt();
		    long[] arr = new long[n*3];
		    for(int i=0;i<3*n;i++){
		        arr[i] = sc.nextLong();
		    }
		    
		    Arrays.sort(arr);
		    for(int i=0,j=arr.length-1;i<j;i++,j--){
		        long temp = arr[i];
		        arr[i] = arr[j];
		        arr[j] = temp;
		    }
		    pref = new long[3*n+1];
		    for(int i=0;i<3*n;i++){
		        pref[i+1] = pref[i]+arr[i];
		    }
		    long ans = 0;
		    for(int a=0;a<=n;a++){
		        int lo = 0;
		        int hi = n-a;
		        while(lo<hi){
		            int mid = (lo+hi)>>>1;
		            if(calc(a,mid)<=calc(a,mid+1)){
		                lo = mid+1;
		            }else{
		                hi = mid;
		            }
		        }
		        ans = Math.max(ans,calc(a,lo));
		    }
		    
		    System.out.println(ans);
		}

	}
}
